        ctx.strokeStyle = "#e8dcc2";
        ctx.globalAlpha = 0.12;
        ctx.strokeRect(x + 0.5, y + 0.5, CELL, CELL);
        ctx.globalAlpha = 1;
        ctx.save();
        ctx.translate(x + CELL * 0.12, y + CELL / 2);
