  async function loadAtoms() {
    const out = {};
    await Promise.all(
      Object.entries(SOURCES).map(async ([name, src]) => {
        const img = new Image();
        img.src = src;
        await img.decode();
        out[name] = { image: img, width: img.naturalWidth, height: img.naturalHeight };
      })
    );
    registerFloraAtoms(out);
  }

  // prototypes/flora/main.ts
  var canvas = document.getElementById("cv");
  var bar = document.getElementById("bar");
  var status = document.getElementById("status");
  function runScene(scene) {
    canvas.width = scene.width;
    canvas.height = scene.height;
    canvas.style.width = `${Math.min(scene.width, 1360)}px`;
    const ctx = canvas.getContext("2d", { alpha: false });
    ctx.save();
    const t0 = performance.now();
    scene.draw(ctx, scene.width, scene.height);
    const ms = Math.round(performance.now() - t0);
    ctx.restore();
    status.textContent = `${scene.name} \u2014 ${scene.width}\xD7${scene.height} \u2014 ${ms}ms`;
    return canvas.toDataURL("image/png");
  }
  for (const scene of SCENES) {
    const b = document.createElement("button");
    b.textContent = scene.name;
    b.onclick = () => runScene(scene);
    bar.insertBefore(b, status);
  }
